package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonStore store, Out<Person> personOut) throws InvalidSheetException {
        Person person = null;
        try {
            person = store.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (person == null) {
            throw new InvalidSheetException("No such person: " + personId);
        }
        personOut.set(person);
    }
}
=== HoldPerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or takes them off it when they are held. */
public class HoldPerson {
    public void hold(@Val Person person, PersonStore store) {
        store.hold(person, !person.isHeld());
    }
}
=== AuditPersonHeld
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a hold: PERSON_HELD sheet=<id> by=<user> name=<name>, or PERSON_RELEASED when taken off it. */
public class AuditPersonHeld {
    public void audit(@Val HoldRequest request, @Val Person person, @Val Rollup before, Audit audit,
            RollupService rollups) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId()
                + " by=" + request.user() + " name=" + person.getName());
        rollups.record(person.getSheetId(), request.user(), before);
    }
}
