import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, StatementStore statements, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person, statements.summary(person.getSheetId(), person.getId())));
    }
}
=== RespondWithPeople
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.statement.StatementStore;
import net.officefloor.hq.app.statement.StatementSummary;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId, PersonStore store,
            StatementStore statements, ObjectResponse<List<PersonResponse>> response) {
        Map<Long, StatementSummary> stated = statements.summaries(sheetId.trim());
        response.send(store.list(sheetId.trim()).stream()
                .map(p -> PersonResponse.from(p, stated.getOrDefault(p.getId(), StatementSummary.NONE))).toList());
    }
}
=== Person
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A person on a sheet. {@code grade} is one of A, B or C; {@code version} moves on with each stored edit;
 *  {@code retiredFrom} is the date they are retired from (null while not retired); {@code held} whether
 *  they are on hold, when their OPEN claims count in no live total. */
public class Person {
    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    private long version;
    private LocalDate retiredFrom;
    private boolean held;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public Person(long id, String sheetId, String name, String grade, long version, LocalDate retiredFrom) {
        this(id, sheetId, name, grade, version);
        this.retiredFrom = retiredFrom;
    }

    public Person(long id, String sheetId, String name, String grade, long version, LocalDate retiredFrom,
            boolean held) {
        this(id, sheetId, name, grade, version, retiredFrom);
        this.held = held;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public String getGrade() { return grade; }
    public long getVersion() { return version; }
    public LocalDate getRetiredFrom() { return retiredFrom; }
    /** Retired as soon as a date is set, whatever the date. */
    public boolean isRetired() { return retiredFrom != null; }
    public boolean isHeld() { return held; }
    public void setHeld(boolean held) { this.held = held; }
    public void setName(String name) { this.name = name; }
    public void setGrade(String grade) { this.grade = grade; }
    public void setVersion(long version) { this.version = version; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
}
=== PersonResponse
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.statement.StatementSummary;

/** A person as the front end reads it, with their statement count and the last statement's
 *  due-total and date (null when none was taken), whether they are retired and from when (null when not), and whether they are on hold. */
public record PersonResponse(long id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom, boolean held) {
    public static PersonResponse from(Person p, StatementSummary s) {
        return new PersonResponse(p.getId(), p.getName(), p.getGrade(), p.getVersion(), s.count(), s.lastDueTotal(),
                s.lastDate(), p.isRetired(),
                p.getRetiredFrom() == null ? null : p.getRetiredFrom().toString(), p.isHeld());
    }
}
