import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../../session/session';

function HoldHead() {
  return <th>Hold</th>;
}

// Whether the person is on hold, and the button that puts them on it or takes them off it. While
// held, their OPEN claims count in no live total. A refused toggle shows its error until the next.
function PersonHold({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();

  const hold = useMutation({
    mutationFn: () => postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/hold`, { user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });

  return (
    <td>
      <span data-testid="person-hold">{person.held ? 'yes' : 'no'}</span>{' '}
      <button
        type="button"
        data-testid="person-hold-toggle"
        disabled={hold.isPending}
        onClick={() => {
          hold.reset();
          hold.mutate();
        }}
      >
        {person.held ? 'Release' : 'Hold'}
      </button>
      {hold.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          {hold.error instanceof HttpError && hold.error.reason ? `${hold.error.reason}.` : 'The hold was refused.'}
        </span>
      )}
    </td>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 19.5, Component: HoldHead }),
  PersonColumns.fill({ order: 19.5, Component: PersonHold }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';
import { sheetKey } from '../sheet/sheet';

/** `version` moves on with each stored edit; an edit is saved only over the version its editor loaded.
 *  `statementCount` is how many statements were taken of them; `statedTotal` (two decimals, or n/a)
 *  and `statementDate` (yyyy-MM-dd) are the last one's, null when none was taken. `retired` is set
 *  as soon as a `retiredFrom` date (yyyy-MM-dd, null when not retired) is, whatever the date.
 *  While `held`, their OPEN claims count in no live total; their SETTLED ones still do. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
};

export const GRADES = ['A', 'B', 'C'] as const;

/** Under the sheet's key, so loading the sheet again re-reads its people. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
}

/** The id of the person whose editor is open in the person form ('' when it adds). */
