import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person, peopleKey, useShowRetired } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../../session/session';

// The "show retired" toggle: the people list leaves retired people out unless it is on. It belongs
// to the screen, so loading a sheet leaves it as it is.
function ShowRetired() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [showRetired, setShowRetired] = useShowRetired();

  if (!user || !sheet) return null;
  return (
    <label>
      <input
        type="checkbox"
        data-testid="show-retired"
        checked={showRetired}
        onChange={(e) => setShowRetired(e.target.checked || undefined)}
      />{' '}
      Show retired
    </label>
  );
}

function RetiredHead() {
  return <th>Retired</th>;
}

// Whether the person is retired and from when, and the date and button that retire them (a blank
// date takes the sheet's today). A refused retirement shows its error until the next is tried.
function PersonRetired({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();

  const retire = useMutation({
    mutationFn: (from: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`, { date: from, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      setDate('');
    },
  });

  return (
    <td>
      <span data-testid="person-retired">{person.retired ? 'yes' : 'no'}</span>{' '}
      <span data-testid="person-retired-from">{person.retiredFrom ?? ''}</span>{' '}
      <input
        type="date"
        data-testid="person-retire-date"
        value={date}
        onChange={(e) => {
          retire.reset();
          setDate(e.target.value);
        }}
      />
      <button
        type="button"
        data-testid="person-retire"
        disabled={retire.isPending}
        onClick={() => {
          retire.reset();
          retire.mutate(date);
        }}
      >
        Retire
      </button>
      {retire.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          {retire.error instanceof HttpError && retire.error.reason ? `${retire.error.reason}.` : 'The retirement was refused.'}
        </span>
      )}
    </td>
  );
}

export const contributions = [
  HomeMain.fill({ order: 18, Component: ShowRetired }),
  PersonColumnHeads.fill({ order: 19, Component: RetiredHead }),
  PersonColumns.fill({ order: 19, Component: PersonRetired }),
];
import type { Claim } from '../claims/claims';
import { type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
import type { Settings } from '../settings/settings';

/** The terms a sheet has until they are set: 14 days. */
export const DEFAULT_TERMS = '14';

/** The claim's due-by (yyyy-MM-dd): its date plus the terms (whole days) in force. */
export function dueBy(claim: Claim, terms: string | undefined): string {
  const d = new Date(`${claim.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + Number(terms ?? DEFAULT_TERMS));
  return d.toISOString().slice(0, 10);
}

/** Whether the claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function overdue(claim: Claim, terms: string | undefined, today: string | undefined): boolean {
  return claim.status === 'OPEN' && today !== undefined && dueBy(claim, terms) < today;
}

const DAY = 24 * 60 * 60 * 1000;

/** How many full 30 days the claim is overdue on the sheet's today (0 when it is not overdue). */
export function latePeriods(claim: Claim, terms: string | undefined, today: string | undefined): number {
  if (today === undefined || !overdue(claim, terms, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim, terms)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}

/** What the sheet's late charge follows: its late percent, its terms and its today. */
export function lateOf(settings: Settings | undefined, today: string | undefined): Late {
  return { pct: settings?.latePct, periods: (c) => latePeriods(c, settings?.terms, today) };
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

